"""Embedded seed data for Decision Ledger — self-contained demo.

50 decisions across 5 categories telling a 6-month story (Jan–Jun 2026)
for Nexura Commerce, a US subscription wellness & beauty box expanding
into Europe.
"""


import pandas as pd

DECISIONS = [
    {"id":1,"title":"Raise base subscription price from $45 to $49 per month","category":"pricing","context":"Nexura has held its base price for 22 months. COGS rose 11% in 2025 driven by ingredient costs and carrier rate increases. Gross margin has compressed from 58% to 51% over that period. The competitive median price is $52/month. NPS sits at 68 — a company record — suggesting meaningful pricing power exists.","options_considered":[{"option":"Hold at $45","pros":["zero churn risk","no customer communication required"],"cons":["margin continues to compress","signals brand weakness"]},{"option":"Raise to $49","pros":["$48/subscriber/year uplift","still $3 below competitor median","funds roadmap investment"],"cons":["estimated 2-4% churn among price-sensitive cohort"]},{"option":"Raise to $52 matching competitors","pros":["maximum margin recovery"],"cons":["high churn risk","sacrifices primary positioning advantage"]}],"data_consulted":["Competitor pricing survey Jan 2026","Price elasticity cohort model (n=12,400)","NPS survey Q4 2025","COGS breakdown report Dec 2025","Churn cohort analysis by tenure"],"decision_made":"Raise base monthly price from $45 to $49, effective 1 Feb 2026, with 60-day advance notice. Offer existing subscribers a 3-month price-lock if they prepay before the change date.","rationale":"At $49 we remain below the $52 competitor median while recovering approximately $1.8M in ARR.","expected_outcome":"Churn rate ≤3% at 90-day review; net ARR lift ≥$1.5M; subscriber NPS does not fall below 62.","review_date":"2026-06-05","status":"succeeded","actual_outcome":"Churn rate at 90-day mark: 2.1% — within threshold. ARR increased $2.4M (8.9% lift). Net subscriber count grew 340, 4.2% above forecast.","team":"Finance","owner":"Nadia Osei","decided_at":"2026-01-05"},
    {"id":2,"title":"Introduce 20% discount for annual billing commitment","category":"pricing","context":"Monthly churn averages 3.8%. Industry data shows annual-plan subscribers churn at 0.6–1.2% annually.","options_considered":[{"option":"No change — keep monthly only","pros":["simplicity"],"cons":["miss retention lever"]},{"option":"20% annual discount ($432/year)","pros":["locks in 12 months of revenue","upfront cash"],"cons":["20% revenue cut on converted subscribers"]},{"option":"15% annual discount","pros":["smaller revenue haircut"],"cons":["less compelling"]}],"data_consulted":["SaaS annual plan conversion benchmarks","Internal cohort churn data 2024-2025"],"decision_made":"Launch annual billing at $432/year (20% discount vs monthly).","rationale":"NPV of a retained annual subscriber exceeds NPV of a monthly subscriber with 3.8% monthly churn.","expected_outcome":"Annual plan attach rate ≥20% within 90 days; upfront cash ≥$800K.","review_date":"2026-04-12","status":"succeeded","actual_outcome":"Annual plan attach rate reached 28% within 90 days. Upfront cash of $1.24M collected.","team":"Finance","owner":"Nadia Osei","decided_at":"2026-01-12"},
    {"id":3,"title":"Launch $29/month Essentials tier with reduced box size","category":"pricing","context":"Funnel data shows a 34% drop-off at the payment step. Exit surveys cite price as the top barrier.","options_considered":[{"option":"No entry tier","pros":["simple pricing"],"cons":["high price-barrier drop-off continues"]},{"option":"$29 Essentials (4 items vs 7)","pros":["removes price barrier","creates upgrade path"],"cons":["cannibalization risk"]},{"option":"Free trial ($10 first box)","pros":["lowest barrier"],"cons":["expensive subsidy"]}],"data_consulted":["Checkout funnel analysis Dec 2025","Exit survey data (n=2,200)"],"decision_made":"Launch $29 Essentials tier (4-item box) in February. Run for 90 days.","rationale":"Exit survey data strongly suggests price is the conversion barrier.","expected_outcome":"Net new incremental subscribers +500 in 90 days with cannibalization ≤8%.","review_date":"2026-05-03","status":"failed","actual_outcome":"18% of existing $49 subscribers downgraded — 3× the risk threshold. Net ARR declined $210K. Tier discontinued April 1.","team":"Growth","owner":"Marco Delgado","decided_at":"2026-02-03"},
    {"id":4,"title":"Deploy dynamic pricing algorithm for new subscriber acquisition","category":"pricing","context":"CAC is rising ($41 in Q4 2025 vs $33 in Q4 2024). Paid acquisition channels showing diminishing returns.","options_considered":[{"option":"Fixed $49 price","pros":["simple","no fairness risk"],"cons":["CAC continues rising"]},{"option":"Dynamic pricing $39–$49","pros":["optimize conversion"],"cons":["fairness risk","brand inconsistency"]},{"option":"Promotional codes via partners","pros":["targeted discounts"],"cons":["limited scale"]}],"data_consulted":["CAC trend analysis 2024-2025","Dynamic pricing case studies"],"decision_made":"Deploy dynamic pricing to 15% of new acquisition traffic as A/B test for 30 days.","rationale":"Personalized pricing is standard in travel and hospitality.","expected_outcome":"CAC reduction ≥15%; conversion rate ≥10% improvement.","review_date":"2026-03-18","status":"reversed","actual_outcome":"Subscribers shared screenshots on Reddit. Complaint volume spiked 280%. Reversed after 22 hours.","team":"Growth","owner":"Marco Delgado","decided_at":"2026-02-18"},
    {"id":5,"title":"Raise gift subscription price by 10%","category":"pricing","context":"Gift subscriptions are 22% of Q4 revenue. Gifters are highly price-insensitive (NPS 74).","options_considered":[{"option":"Hold gift pricing","pros":["no risk"],"cons":["continuing margin gap"]},{"option":"Raise gift price 10%","pros":["aligns with real COGS"],"cons":["small risk of volume drop"]},{"option":"Remove gift discount entirely","pros":["full margin recovery"],"cons":["meaningful price shock"]}],"data_consulted":["Gift subscription margin analysis Q4 2025","Gifter NPS survey (n=890)"],"decision_made":"Raise all gift subscription prices by 10%, effective March 15.","rationale":"Gifter cohort shows NPS 74 — most satisfied and least price-sensitive buyers.","expected_outcome":"Gift revenue +8%; gift unit volume decline ≤5%.","review_date":"2026-06-10","status":"succeeded","actual_outcome":"Gift revenue increased 19%. Unit volume declined 1.8%. AOV on multi-month bundles up $14.20.","team":"Finance","owner":"Nadia Osei","decided_at":"2026-03-10"},
    {"id":6,"title":"Launch loyalty pricing: 15% discount for 12+ month subscribers","category":"pricing","context":"Long-tenure subscribers (12mo+) have 91% annual retention and NPS 79.","options_considered":[{"option":"No loyalty pricing","pros":["protects margin"],"cons":["vulnerability to competitor poaching"]},{"option":"15% discount at 12mo anniversary","pros":["rewards highest-LTV segment"],"cons":["margin reduction on retained customers"]},{"option":"Free gift at anniversary","pros":["tangible reward"],"cons":["operationally complex"]}],"data_consulted":["Subscriber tenure retention curve","Competitor loyalty program benchmarking"],"decision_made":"Introduce 15% loyalty discount at 12-month anniversary.","rationale":"The 15% discount costs ~$88/year but retains a subscriber worth ~$520 annual ARR.","expected_outcome":"Loyalty cohort 12-month retention ≥95%.","review_date":"2026-07-25","status":"active","actual_outcome":None,"team":"Finance","owner":"Nadia Osei","decided_at":"2026-03-25"},
    {"id":7,"title":"Launch $69/month bundle combining Skincare and Wellness boxes","category":"pricing","context":"14% of customers subscribe to both separate boxes ($98 total).","options_considered":[{"option":"Keep separate boxes","pros":["simple"],"cons":["no upsell lever"]},{"option":"$69 combined bundle","pros":["$20 savings vs dual-box","strong upsell"],"cons":["reduces ARR for existing dual-box subscribers"]},{"option":"$79 bundle","pros":["less ARR dilution"],"cons":["less compelling"]}],"data_consulted":["Dual-subscriber cohort analysis","Bundle pricing case studies"],"decision_made":"Launch $69/month Nexura Complete bundle.","rationale":"Bundle pricing reduces per-unit cost while increasing revenue per customer.","expected_outcome":"Bundle conversion ≥8% of single-category subscribers within 90 days.","review_date":"2026-08-08","status":"active","actual_outcome":None,"team":"Product","owner":"Lena Fischer","decided_at":"2026-04-08"},
    {"id":8,"title":"Set UK market pricing in GBP with local purchasing power parity","category":"pricing","context":"UK customers billed in USD, creating FX exposure and poor experience.","options_considered":[{"option":"Keep billing in USD","pros":["simple"],"cons":["customer friction","FX exposure"]},{"option":"£38/month GBP pricing","pros":["market-norm","removes FX risk"],"cons":["GBP/USD reporting complexity"]},{"option":"£40/month","pros":["maximizes revenue"],"cons":["above UK market average"]}],"data_consulted":["UK subscription market pricing report","FX exposure analysis"],"decision_made":"Switch UK billing to £38/month GBP.","rationale":"Local currency billing is standard for serious UK market entrants.","expected_outcome":"UK checkout conversion +15%; FX support tickets to zero.","review_date":"2026-08-02","status":"active","actual_outcome":None,"team":"Finance","owner":"Nadia Osei","decided_at":"2026-05-02"},
    {"id":9,"title":"Establish flash sale cadence: quarterly 72-hour 30% off promotions","category":"pricing","context":"Ad-hoc promotions with inconsistent results. 2-4× normal acquisition during windows.","options_considered":[{"option":"No flash sales","pros":["protects brand"],"cons":["missed acquisition peaks"]},{"option":"Quarterly 72-hour 30% off","pros":["creates urgency","predictable bursts"],"cons":["promotion-acquired LTV 22% lower"]},{"option":"Monthly 20% off first box","pros":["consistent"],"cons":["always-on discounting"]}],"data_consulted":["Historical promotion performance","LTV cohort analysis"],"decision_made":"Run quarterly 72-hour flash sales at 30% off first month.","rationale":"Structured cadence enables supply chain and marketing planning.","expected_outcome":"≥600 new subscribers per flash sale; blended CAC ≤$48.","review_date":"2026-08-20","status":"active","actual_outcome":None,"team":"Growth","owner":"Marco Delgado","decided_at":"2026-05-20"},
    {"id":10,"title":"Implement channel price parity across all distribution points","category":"pricing","context":"Prices inconsistent across website, iOS app, and retail partners.","options_considered":[{"option":"Allow price variance","pros":["simple"],"cons":["customer confusion","arbitrage"]},{"option":"Enforce price parity","pros":["clean experience","no arbitrage"],"cons":["app and retail economics worse"]},{"option":"Close retail, adjust app","pros":["maximizes direct margin"],"cons":["lose retail presence"]}],"data_consulted":["Channel margin analysis","Apple App Store commission review"],"decision_made":"Enforce price parity at $49 across all channels.","rationale":"Price parity is prerequisite for brand consistency.","expected_outcome":"Zero price discrepancy complaints; retail contract renegotiation by Q3.","review_date":"2026-09-03","status":"active","actual_outcome":None,"team":"Finance","owner":"Nadia Osei","decided_at":"2026-06-03"},
    {"id":11,"title":"Launch Nexura iOS mobile application","category":"product","context":"Mobile is 61% of traffic but only 31% of conversions. 68% of mobile visitors use iPhone.","options_considered":[{"option":"Mobile web only","pros":["no dev cost"],"cons":["30-point conversion gap persists"]},{"option":"iOS app first, Android 90 days later","pros":["captures 68% of mobile visitors"],"cons":["Android users wait"]},{"option":"React Native cross-platform","pros":["one codebase"],"cons":["slower initial development"]}],"data_consulted":["Mobile traffic vs conversion analysis","iOS vs Android split"],"decision_made":"Build and ship native iOS app by February 1.","rationale":"Native app will close mobile conversion gap via Apple Pay and push notifications.","expected_outcome":"App Store rating ≥4.5/5; ≥50% active subscribers adopt app within 90 days.","review_date":"2026-04-08","status":"succeeded","actual_outcome":"App Store rating: 4.7/5. 68% of subscribers using app as primary channel. Mobile conversion improved from 31% to 54%.","team":"Product","owner":"Lena Fischer","decided_at":"2026-01-08"},
    {"id":12,"title":"Redesign personalization quiz with adaptive branching logic","category":"product","context":"Current 8-question quiz has 61% completion rate and 3.1/5 product relevance.","options_considered":[{"option":"Keep v1 quiz","pros":["stable"],"cons":["61% completion is revenue leak"]},{"option":"Adaptive v2 quiz (5-12 questions)","pros":["higher completion","better personalization"],"cons":["2-week dev effort"]},{"option":"Skip quiz — use purchase history","pros":["no friction"],"cons":["cold start problem"]}],"data_consulted":["Quiz funnel analysis (Mixpanel)","Post-box survey: relevance rating"],"decision_made":"Build adaptive-branching quiz v2. A/B test for 30 days.","rationale":"Primary failure is generic questions that don't adapt to the respondent.","expected_outcome":"Quiz completion ≥80%; relevance rating ≥4.0/5.","review_date":"2026-04-15","status":"succeeded","actual_outcome":"Completion: 84%. Relevance: 4.2/5. 90-day retention for v2 completers: 87% vs 74% for non-completers.","team":"Product","owner":"Lena Fischer","decided_at":"2026-01-15"},
    {"id":13,"title":"Build AI-powered product recommendation engine","category":"product","context":"Static 'You might also like' section. Add-on purchase rate 8.4%.","options_considered":[{"option":"Keep static recs","pros":["no engineering cost"],"cons":["8.4% add-on rate is low"]},{"option":"Collaborative filtering engine","pros":["personalized at scale","proven lift"],"cons":["6-8 weeks engineering"]},{"option":"Rule-based personalization","pros":["fast"],"cons":["doesn't learn over time"]}],"data_consulted":["Add-on purchase funnel analysis","Recommendation engine benchmarks"],"decision_made":"Build collaborative filtering recommendation engine.","rationale":"18 months of purchase data and a dedicated data science team.","expected_outcome":"Add-on rate lift to ≥12%; recommendation CTR ≥20%.","review_date":"2026-05-05","status":"succeeded","actual_outcome":"Add-on rate: 13.1%. CTR: 26%. Incremental add-on revenue: $420K in 90 days.","team":"Product","owner":"Priya Menon","decided_at":"2026-02-05"},
    {"id":14,"title":"Launch virtual try-on AR feature for skincare products","category":"product","context":"Beauty industry shows AR try-on drives 30-40% conversion lifts.","options_considered":[{"option":"No AR feature","pros":["$96K/year saved"],"cons":["competitors deploying AR"]},{"option":"License Perfect Corp SDK for 90-day trial","pros":["fastest path","proven tech"],"cons":["$24K for trial","may not suit our positioning"]},{"option":"Build in-house AR","pros":["full ownership"],"cons":["6+ month build"]}],"data_consulted":["ModiFace AR conversion lift report","Perfect Corp SDK demo"],"decision_made":"License Perfect Corp AR SDK for 90-day trial on color cosmetics (40% of boxes).","rationale":"Industry data shows meaningful lift for color cosmetics.","expected_outcome":"AR engagement ≥20%; satisfaction ≥4.3/5; trial ROI positive.","review_date":"2026-05-20","status":"failed","actual_outcome":"Engagement: 4.2% — 5× below target. 72% rated it 'too inaccurate' for skincare. Feature deprecated after 60 days. Cost: $84K.","team":"Product","owner":"Lena Fischer","decided_at":"2026-02-20"},
    {"id":15,"title":"Transition to 100% recycled and biodegradable outer packaging","category":"product","context":"81% of subscribers consider environmental impact. Zero-cost switch via volume commit.","options_considered":[{"option":"Keep current packaging","pros":["no change"],"cons":["reputational lag"]},{"option":"100% recycled/biodegradable at same cost","pros":["brand alignment","no cost increase"],"cons":["18-month volume commit"]},{"option":"Partial transition","pros":["lower commitment"],"cons":["half-measure"]}],"data_consulted":["Subscriber sustainability survey (n=3,200)","Supplier quote: EcoPackaging Partners"],"decision_made":"Full transition to recycled outer box + biodegradable kraft fill by March 31.","rationale":"Cost-neutral sustainability is a clear win with 81% subscriber support.","expected_outcome":"NPS ≥5 point improvement; zero damage-rate increase.","review_date":"2026-06-03","status":"succeeded","actual_outcome":"NPS +8 points (68→76). Damage rate flat at 2.1%. COGS: no increase. Social mentions +34%.","team":"Product","owner":"Lena Fischer","decided_at":"2026-03-03"},
    {"id":16,"title":"Add subscription pause feature: up to 2 months per year","category":"product","context":"31% of cancellations cite 'taking a break' rather than dissatisfaction.","options_considered":[{"option":"No pause — cancel or continue","pros":["simple billing"],"cons":["31% of cancels are preventable"]},{"option":"Pause up to 2 months/year","pros":["captures recoverable cancels"],"cons":["small MRR dip while paused"]},{"option":"Skip a single month","pros":["simpler"],"cons":["doesn't address multi-month events"]}],"data_consulted":["Exit survey: cancellation reasons","Competitor feature audit"],"decision_made":"Launch pause feature: 1 or 2 months, up to twice per year.","rationale":"31% of cancels are pause-motivated; retaining 40% saves ~$70K ARR annually.","expected_outcome":"Pause usage ≥10% of cancel-intent; 90-day return rate ≥60%.","review_date":"2026-06-18","status":"succeeded","actual_outcome":"Usage by 14% of cancel-intent subscribers. 71% reactivated. Net cancel rate fell 0.8pp. ARR saved: $88K in 90 days.","team":"Product","owner":"Lena Fischer","decided_at":"2026-03-18"},
    {"id":17,"title":"Launch Nexura Android mobile application","category":"product","context":"iOS app exceeded targets. Android is 32% of mobile visitors with no native app.","options_considered":[{"option":"Delay Android","pros":["avoid fragmentation"],"cons":["32% underserved"]},{"option":"Native Android","pros":["best experience"],"cons":["14 weeks"]},{"option":"React Native port","pros":["faster — 8 weeks"],"cons":["slightly lower performance"]}],"data_consulted":["Android vs iOS traffic and LTV","React Native feasibility review"],"decision_made":"Build Android app using React Native, targeting July 2.","rationale":"React Native enables 8-week build by sharing iOS components. Critical for EU expansion.","expected_outcome":"Google Play rating ≥4.4/5; Android conversion improvement ≥15%.","review_date":"2026-07-02","status":"active","actual_outcome":None,"team":"Product","owner":"Lena Fischer","decided_at":"2026-04-02"},
    {"id":18,"title":"Launch social sharing feature with referral reward ($15 credit)","category":"product","context":"Word-of-mouth is 22% of acquisitions with no structured referral program.","options_considered":[{"option":"No referral program","pros":["no cost"],"cons":["leave organic WOM unmonetized"]},{"option":"$15 credit for referrer","pros":["aligned incentive","$15 < $41 CAC"],"cons":["fraud prevention needed"]},{"option":"$15 for both sides","pros":["stronger incentive"],"cons":["$30 total cost"]}],"data_consulted":["Acquisition source survey","Referral program benchmarks"],"decision_made":"$15 account credit for referrer when referred subscriber completes first box.","rationale":"One-sided referral has lower fraud surface. $15 is 37% of CAC.","expected_outcome":"≥150 new subscribers/month by month 3; referral CAC ≤$20.","review_date":"2026-08-16","status":"active","actual_outcome":None,"team":"Growth","owner":"Marco Delgado","decided_at":"2026-04-16"},
    {"id":19,"title":"Integrate third-party gift card marketplace","category":"product","context":"Gift subs are 22% of Q4 revenue. Gift cards reach impulse buyers.","options_considered":[{"option":"No gift card marketplace","pros":["simple"],"cons":["miss distribution"]},{"option":"Integrate GiftCards.com and Raise","pros":["incremental distribution","net-new audience"],"cons":["5-8% commission"]},{"option":"Own gift card system","pros":["100% margin"],"cons":["no new reach"]}],"data_consulted":["Gift card marketplace traffic analysis","Raise integration API docs"],"decision_made":"Integrate on GiftCards.com and Raise at 7% commission.","rationale":"Marketplaces reach a different buyer profile — impulse gift buyers.","expected_outcome":"≥100 units/month by month 3; redemption rate ≥65%.","review_date":"2026-09-07","status":"active","actual_outcome":None,"team":"Product","owner":"Lena Fischer","decided_at":"2026-05-07"},
    {"id":20,"title":"Build in-app skincare routine builder tool","category":"product","context":"Top churn driver: 'not sure how to use all the products.'","options_considered":[{"option":"Static blog posts","pros":["fast"],"cons":["not personalized"]},{"option":"Interactive in-app routine builder","pros":["personalized to box contents","increases app engagement"],"cons":["4-week build"]},{"option":"Video tutorials","pros":["high engagement"],"cons":["production cost high"]}],"data_consulted":["Churn exit survey analysis","App engagement session analysis"],"decision_made":"Build personalized routine builder generating morning/night routine cards.","rationale":"31% of voluntary churn is product-confusion-driven.","expected_outcome":"Engagement ≥35% within 30 days; voluntary churn decrease ≥0.4pp.","review_date":"2026-09-22","status":"active","actual_outcome":None,"team":"Product","owner":"Lena Fischer","decided_at":"2026-05-22"},
    {"id":21,"title":"Launch subscriber community forum (MVP)","category":"product","context":"14,000-member Facebook group formed organically. Community is a proven retention lever.","options_considered":[{"option":"Leave on Facebook","pros":["zero cost"],"cons":["no data ownership"]},{"option":"Build owned forum","pros":["data ownership","product integration"],"cons":["8-week build","cold start"]},{"option":"Use Discourse","pros":["faster — 2 weeks"],"cons":["less integrated"]}],"data_consulted":["Facebook group analysis","Competitor community analysis"],"decision_made":"Build owned community forum MVP in 8 weeks with migration campaign.","rationale":"Owning community data is strategically critical.","expected_outcome":"MAU ≥3,000 in 90 days; Facebook migration ≥30%.","review_date":"2026-10-05","status":"active","actual_outcome":None,"team":"Product","owner":"Lena Fischer","decided_at":"2026-06-05"},
    {"id":22,"title":"Add product review and rating system","category":"product","context":"No structured product feedback. Curation relies on supplier data and buyer judgment.","options_considered":[{"option":"No ratings","pros":["no cost"],"cons":["curation stays judgment-based"]},{"option":"5-star + optional text review","pros":["rich signal","social proof"],"cons":["4-week build","moderation needed"]},{"option":"Thumbs up/down only","pros":["1 week build"],"cons":["less granular signal"]}],"data_consulted":["Recommendation engine data requirements","Competitor review systems"],"decision_made":"Build 5-star rating with optional text review, triggered 7 days post-delivery.","rationale":"5-star ratings provide the quality signal the recommendation engine needs.","expected_outcome":"Rating submission ≥40% of deliveries; ≥8 ratings per product per month.","review_date":"2026-10-18","status":"active","actual_outcome":None,"team":"Product","owner":"Priya Menon","decided_at":"2026-06-18"},
    {"id":23,"title":"Hire Head of Data Science","category":"hiring","context":"Outsourcing ML to consultancy at $22K/month. Roadmap needs sustained ML investment.","options_considered":[{"option":"Continue with consultancy","pros":["flexible"],"cons":["$264K/year with no IP"]},{"option":"Hire Head of Data Science ($180K)","pros":["permanent capability","IP ownership"],"cons":["6-8 week timeline"]},{"option":"Mid-level ML engineer","pros":["lower cost"],"cons":["lacks strategic vision"]}],"data_consulted":["ML consultancy invoices ($264K/year)","Head of DS salary benchmarks"],"decision_made":"Hire Head of Data Science at $180K. Terminate consultancy on hire start date.","rationale":"ML roadmap requires sustained, fast-iteration capability consultancies can't provide.","expected_outcome":"Hired by March 1; consultancy terminated; first ML model within 45 days.","review_date":"2026-04-06","status":"succeeded","actual_outcome":"Priya Menon hired Feb 15. Consultancy terminated same day. Recommendation engine shipped March 8 — 21 days.","team":"People","owner":"James Okafor","decided_at":"2026-01-06"},
    {"id":24,"title":"Expand Customer Success team from 8 to 13 agents","category":"hiring","context":"3,200 tickets/week with 18-hour response time. Industry benchmark is 4 hours.","options_considered":[{"option":"Hold at 8 — improve tooling","pros":["no cost"],"cons":["18 hours is a real churn driver"]},{"option":"Hire 5 agents","pros":["closes response time gap"],"cons":["$280K cost"]},{"option":"Hire 3 + chatbot","pros":["smaller investment"],"cons":["chatbot takes 8 weeks"]}],"data_consulted":["CS ticket volume analysis","CSAT survey 2025 (3.8/5)","Response time benchmarks"],"decision_made":"Hire 5 CS agents. Promote Emma Park to Team Lead.","rationale":"18-hour response time is 4.5× above industry benchmark — cannot be solved by tooling alone.","expected_outcome":"Response time ≤4 hours within 60 days; CSAT ≥4.3/5.","review_date":"2026-03-20","status":"succeeded","actual_outcome":"All 5 hired by Feb 26. Response time: 3.8 hours. CSAT: 4.5/5. CS churn mentions fell 48%.","team":"People","owner":"James Okafor","decided_at":"2026-01-20"},
    {"id":25,"title":"Hire 2 Senior Backend Engineers for reliability","category":"hiring","context":"API p95 latency 840ms (target 350ms). 2 payment outages in Q4 totaling 4.2 hours.","options_considered":[{"option":"Reassign existing engineers","pros":["immediate"],"cons":["stops product delivery"]},{"option":"Hire 2 Senior Backend Engineers ($175K each)","pros":["permanent capacity"],"cons":["8-week timeline"]},{"option":"1 engineer + contract SRE","pros":["faster"],"cons":["contractor at $200/hr is expensive"]}],"data_consulted":["API performance report Q4 2025","Payment outage postmortems"],"decision_made":"Hire 2 Senior Backend Engineers. March 1 start.","rationale":"Latency and payment reliability are blocking growth.","expected_outcome":"API p95 ≤350ms; payment uptime ≥99.95%.","review_date":"2026-04-04","status":"succeeded","actual_outcome":"API p95: 290ms. Payment uptime: 99.97%. Engineers shipped OpenTelemetry and payment retry logic in 4 weeks.","team":"People","owner":"James Okafor","decided_at":"2026-02-04"},
    {"id":26,"title":"Hire Vice President of Marketing","category":"hiring","context":"No VP-level marketing leader for 9 months. Need EU expansion marketing leadership.","options_considered":[{"option":"Promote Marketing Director internally","pros":["institutional knowledge"],"cons":["lacks paid acquisition scale experience"]},{"option":"External VP hire ($210K)","pros":["EU-market experience"],"cons":["6-10 week search"]},{"option":"Fractional CMO","pros":["faster"],"cons":["cannot own execution"]}],"data_consulted":["Marketing function audit","VP Marketing salary benchmarks"],"decision_made":"Hire external VP Marketing with EU experience at $210K.","rationale":"EU expansion requires someone who has done this before.","expected_outcome":"VP hired by March 1; EU marketing strategy by April 15.","review_date":"2026-05-16","status":"failed","actual_outcome":"Alex Torres hired March 1. Strategic misalignment with PLG model. Resigned day 58. Total cost: $90K. EU strategy not delivered.","team":"People","owner":"James Okafor","decided_at":"2026-02-16"},
    {"id":27,"title":"Hire 3 ML Engineers to scale data science team","category":"hiring","context":"Head of DS Priya Menon is bandwidth-constrained. Roadmap needs 3 more engineers.","options_considered":[{"option":"Hire 1 now, more later","pros":["lower burn"],"cons":["churn predictor and forecasting slip 6+ months"]},{"option":"Hire 3 ML engineers ($155K each)","pros":["fully staffed for 2026 roadmap"],"cons":["$420K cost"]},{"option":"Expand consultancy","pros":["flexible"],"cons":["already proven inefficient"]}],"data_consulted":["ML roadmap requirements","ML engineer salary benchmarks"],"decision_made":"Hire 3 ML Engineers at $155K each. Target April 1 start.","rationale":"Priya can ship models fast but cannot do it alone at roadmap pace.","expected_outcome":"All 3 hired by April 1; churn model by May 15; stockout reduction ≥30% by June 1.","review_date":"2026-06-06","status":"succeeded","actual_outcome":"All started April 1. Churn model: 82% precision. Stockout rate reduced from 8.1% to 2.3% (71% reduction).","team":"People","owner":"James Okafor","decided_at":"2026-03-06"},
    {"id":28,"title":"Outsource QA testing function to offshore partner","category":"hiring","context":"2 internal QA engineers at $130K each. Offshore partner offers coverage at $4,200/month.","options_considered":[{"option":"Keep internal QA","pros":["deep product knowledge"],"cons":["$260K/year"]},{"option":"Outsource to Testify Pro","pros":["$215K/year savings"],"cons":["ramp-up time","quality gap risk"]},{"option":"Hybrid: 1 internal + outsource 2","pros":["quality oversight"],"cons":["complex management"]}],"data_consulted":["QA cost analysis","Testify Pro proposal","Internal defect escape rate: 0.8%"],"decision_made":"Full transition to Testify Pro with 30-day overlap.","rationale":"Cost savings are real; references were positive.","expected_outcome":"Defect escape rate ≤1.2%; no P0 bugs in 60 days.","review_date":"2026-05-22","status":"reversed","actual_outcome":"Defect escape rate: 4.1% — 5× baseline. P1 payment bug reached production. Contract terminated. Internal team retained.","team":"Engineering","owner":"Paulo Rivera","decided_at":"2026-03-22"},
    {"id":29,"title":"Hire 2 Product Managers for core and growth tracks","category":"hiring","context":"1 PM managing 12-person team. PM capacity is primary product bottleneck.","options_considered":[{"option":"Hold at 1 PM","pros":["no cost"],"cons":["Lena at risk of burnout"]},{"option":"Hire 2 PMs","pros":["doubles capacity"],"cons":["$280K cost"]},{"option":"Hire 1 senior PM","pros":["lower cost"],"cons":["doesn't relieve bottleneck"]}],"data_consulted":["Product delivery velocity report","PM capacity model"],"decision_made":"Hire Core Product PM and Growth PM. Promote Lena to VP Product.","rationale":"Single PM for a 12-person team is unsustainable.","expected_outcome":"Both hired by June 15; cycle time reduced ≥20%.","review_date":"2026-08-10","status":"active","actual_outcome":None,"team":"People","owner":"James Okafor","decided_at":"2026-04-10"},
    {"id":30,"title":"Hire Director of International Expansion","category":"hiring","context":"CEO spending 40% of time on EU operations. 4 active and 4 planned EU markets.","options_considered":[{"option":"CEO continues managing EU","pros":["no cost"],"cons":["unsustainable"]},{"option":"Hire Director ($160K)","pros":["dedicated ownership"],"cons":["6-8 week search"]},{"option":"Promote UK manager","pros":["market knowledge"],"cons":["lacks multi-country experience"]}],"data_consulted":["CEO time audit (40% on EU)","EU expansion roadmap"],"decision_made":"Hire Director with European subscription commerce experience. July 1 target.","rationale":"EU complexity has passed the threshold for a dedicated leader.","expected_outcome":"Hired by July 1; France/Spain on track by Q3.","review_date":"2026-08-24","status":"active","actual_outcome":None,"team":"People","owner":"James Okafor","decided_at":"2026-04-24"},
    {"id":31,"title":"Hire 4 EU-based Customer Success representatives","category":"hiring","context":"UK subscribers experience 14-hour response delays. France/Spain need native language support.","options_considered":[{"option":"US CS for all markets","pros":["single team"],"cons":["14-hour timezone gap"]},{"option":"4 EU agents (2 UK, 1 France, 1 Spain)","pros":["timezone + language coverage"],"cons":["$260K cost"]},{"option":"Outsource EU CS","pros":["faster"],"cons":["BPO quality risk — see decision 28"]}],"data_consulted":["UK response time analysis","CS ticket language breakdown"],"decision_made":"Hire 4 EU CS reps. All report to Emma Park. August 1 target.","rationale":"Timezone-appropriate, language-native CS is non-negotiable for EU scaling.","expected_outcome":"EU response time ≤4 hours; EU CSAT ≥4.2/5.","review_date":"2026-09-12","status":"active","actual_outcome":None,"team":"People","owner":"James Okafor","decided_at":"2026-05-12"},
    {"id":32,"title":"Hire Chief Financial Officer to replace departing CFO","category":"hiring","context":"CFO departing July 31. EU expansion creating multi-currency and VAT complexity. Series B upcoming.","options_considered":[{"option":"Promote VP Finance internally","pros":["institutional knowledge"],"cons":["lacks fundraising experience"]},{"option":"External CFO ($240K)","pros":["fundraising + EU financial expertise"],"cons":["8-10 week search"]},{"option":"Interim fractional CFO","pros":["buys time"],"cons":["investors prefer FTE"]}],"data_consulted":["Series B preparation requirements","EU VAT compliance assessment"],"decision_made":"External CFO search via Korn Ferry. July 15 target offer acceptance.","rationale":"Series B and EU financial complexity require direct experience.","expected_outcome":"CFO hired by Aug 15; Series B prep within 30 days; VAT framework by Q3.","review_date":"2026-10-10","status":"active","actual_outcome":None,"team":"People","owner":"James Okafor","decided_at":"2026-06-10"},
    {"id":33,"title":"Launch Nexura in the United Kingdom market","category":"market_entry","context":"UK is £1.2B subscription box market. UK-REACH compliance achievable in 60 days.","options_considered":[{"option":"Delay UK","pros":["operational simplicity"],"cons":["first-mover advantage diminishing"]},{"option":"UK via Clipper Logistics 3PL","pros":["fastest to market"],"cons":["3PL margin hit of £2.80/box"]},{"option":"UK warehouse","pros":["full control"],"cons":["18-month setup, £400K capex"]}],"data_consulted":["UK market sizing (Mintel 2025)","Clipper Logistics proposal"],"decision_made":"Launch UK via Clipper Logistics 3PL. First deliveries February 15.","rationale":"UK is clearest path: English-language content, achievable compliance, proven brand pull.","expected_outcome":"≥1,000 UK subscribers in 90 days; UK CAC ≤£35.","review_date":"2026-04-10","status":"succeeded","actual_outcome":"1,240 subscribers at 90 days (24% above forecast). CAC: £31. LTV 6-month proxy: £91. CSAT: 4.4/5.","team":"Growth","owner":"Marco Delgado","decided_at":"2026-01-10"},
    {"id":34,"title":"Expand into Canada: English-speaking provinces first","category":"market_entry","context":"Canada is geographically adjacent, English-speaking. Can fulfill from Ohio FC.","options_considered":[{"option":"Skip Canada","pros":["focus on EU"],"cons":["lowest-friction expansion possible"]},{"option":"Canada via DHL from Ohio","pros":["no new infrastructure"],"cons":["3-5 day delivery"]},{"option":"Canadian 3PL","pros":["faster delivery"],"cons":["4-6 month setup"]}],"data_consulted":["Canada cross-border feasibility","DHL Express Canada pricing"],"decision_made":"Launch Canada via DHL from Ohio FC. C$65/month.","rationale":"Ohio-to-Canada is already tested by DHL. Low-risk validation.","expected_outcome":"≥500 Canadian subscribers in 90 days; CAC ≤C$45.","review_date":"2026-05-06","status":"succeeded","actual_outcome":"662 subscribers (32% above target). CAC: C$38. Unit margin: 38%. Avg delivery: 3.8-4.2 days.","team":"Growth","owner":"Marco Delgado","decided_at":"2026-02-06"},
    {"id":35,"title":"Launch in the Australian market targeting major metros","category":"market_entry","context":"Australia has $380M sub box market. English-speaking, high income.","options_considered":[{"option":"Skip Australia","pros":["focus on EU"],"cons":["opportunity is real"]},{"option":"US shipping + Australia Post","pros":["no new infrastructure"],"cons":["$28-34 AUD shipping","12-17 day delivery"]},{"option":"Australian 3PL first","pros":["sustainable economics"],"cons":["6-month delay"]}],"data_consulted":["Australia market sizing","US-to-Australia shipping quotes"],"decision_made":"Launch via DHL Express Australia. $50K test budget over 60 days.","rationale":"English-speaking markets are highest-success profile.","expected_outcome":"≥300 subscribers in 60 days; positive unit economics at AUD$89.","review_date":"2026-05-22","status":"failed","actual_outcome":"142 subscribers (53% of target). Landed cost AUD$31/box (vs AUD$18 model). Business case negative. Market exit May 2.","team":"Growth","owner":"Marco Delgado","decided_at":"2026-02-22"},
    {"id":36,"title":"Germany market entry via B2B corporate gifting","category":"market_entry","context":"Germany is largest EU economy. B2B gifting avoids German-language and GDPR complexity.","options_considered":[{"option":"Germany DTC launch","pros":["full market access"],"cons":["German content + GDPR complex"]},{"option":"Germany via B2B HR platforms","pros":["lower regulatory bar"],"cons":["limited scale"]},{"option":"Skip Germany — France first","pros":["France DTC model planned"],"cons":["miss largest EU market"]}],"data_consulted":["Germany wellness market sizing","B2B gifting platform landscape"],"decision_made":"Pursue B2B entry via 2-3 HR wellbeing platforms.","rationale":"B2B reduces language and regulatory barrier.","expected_outcome":"First corporate contract by April 30; ≥500 B2B units in Q2.","review_date":"2026-06-12","status":"superseded","actual_outcome":"B2B model de-prioritized. DTC analysis showed 3.2× higher LTV. Germany DTC planned Q1 2027.","team":"Growth","owner":"Marco Delgado","decided_at":"2026-03-12"},
    {"id":37,"title":"France DTC launch: first non-English market entry","category":"market_entry","context":"France is Europe's second-largest beauty market (€4.2B).","options_considered":[{"option":"Delay France until Germany proven","pros":["sequential learning"],"cons":["early entry advantage real"]},{"option":"France DTC via Relais Colis","pros":["same model as UK"],"cons":["translation cost €8K"]},{"option":"France via Amazon.fr","pros":["fast"],"cons":["erodes brand"]}],"data_consulted":["France beauty market sizing","Relais Colis proposal"],"decision_made":"Launch France DTC via Relais Colis. French-language site. August 15 first deliveries.","rationale":"France is natural second EU market. French cosmetics culture aligns with positioning.","expected_outcome":"≥600 French subscribers in 90 days; CAC ≤€40.","review_date":"2026-08-05","status":"active","actual_outcome":None,"team":"Growth","owner":"Marco Delgado","decided_at":"2026-04-05"},
    {"id":38,"title":"Spain market entry: 90 days after France","category":"market_entry","context":"Spain is 5th-largest EU economy with +28% YoY wellness subscription growth.","options_considered":[{"option":"Spain alongside France","pros":["no delay"],"cons":["operational risk"]},{"option":"Spain 90 days after France","pros":["apply France learning"],"cons":["90-day delay"]},{"option":"Skip Spain","pros":["focus"],"cons":["opportunity cost"]}],"data_consulted":["Spain subscription market sizing","Spain 3PL options"],"decision_made":"Launch Spain 90 days after France via MRW. November 15 target.","rationale":"Sequential entry allows operational learning transfer.","expected_outcome":"≥400 Spanish subscribers in 90 days; CAC ≤€42.","review_date":"2026-08-20","status":"active","actual_outcome":None,"team":"Growth","owner":"Marco Delgado","decided_at":"2026-04-20"},
    {"id":39,"title":"Netherlands market entry: English-friendly low-friction test","category":"market_entry","context":"Netherlands has #1 EU English proficiency. Zero translation cost.","options_considered":[{"option":"Skip — too small","pros":["focus on larger markets"],"cons":["zero-localization-cost is too good to skip"]},{"option":"English content via PostNL","pros":["zero translation cost"],"cons":["smaller market"]},{"option":"German-language content","pros":["covers Belgium too"],"cons":["Dutch consumers prefer Dutch or English"]}],"data_consulted":["EU English proficiency index","PostNL pricing"],"decision_made":"Launch Netherlands with English content via PostNL. September 14.","rationale":"No-translation EU entry validates English-language brand potential.","expected_outcome":"≥250 Dutch subscribers in 90 days; CAC ≤€38.","review_date":"2026-09-14","status":"active","actual_outcome":None,"team":"Growth","owner":"Marco Delgado","decided_at":"2026-05-14"},
    {"id":40,"title":"Nordics regional launch (Sweden, Denmark, Norway)","category":"market_entry","context":"Nordics have highest wellness spending per capita in EU. Near-universal English proficiency.","options_considered":[{"option":"Nordics individually","pros":["focused learning"],"cons":["splitting a regional cluster is suboptimal"]},{"option":"Nordics as cluster via PostNord","pros":["regional 3PL","cross-border creators"],"cons":["3 currencies"]},{"option":"Via Amazon.se","pros":["fast"],"cons":["brand erosion"]}],"data_consulted":["Nordic wellness market sizing","PostNord proposal"],"decision_made":"Launch as regional cluster via PostNord. October 6 first deliveries.","rationale":"Geographically and culturally contiguous — cluster launch more efficient.","expected_outcome":"≥350 combined subscribers in 90 days; CAC ≤€45.","review_date":"2026-10-06","status":"active","actual_outcome":None,"team":"Growth","owner":"Marco Delgado","decided_at":"2026-06-06"},
    {"id":41,"title":"Relocate fulfillment center from New Jersey to Ohio","category":"operational","context":"NJ FC has 5.2-day avg delivery. Ohio puts 71% of subscribers in 2-day zone. Saves $2.30/unit.","options_considered":[{"option":"Renew NJ","pros":["continuity"],"cons":["miss $345K ARR saving"]},{"option":"Move to Columbus Ohio","pros":["$2.30/unit saving","3.1-day avg"],"cons":["6-week transition"]},{"option":"Dual facility","pros":["optimal coverage"],"cons":["prohibitive at current scale"]}],"data_consulted":["Shipbob Columbus pricing","UPS zone analysis"],"decision_made":"Transition to Shipbob Columbus with 3-week parallel run.","rationale":"Saves $345K annually while improving delivery for 71% of subscribers.","expected_outcome":"Shipping cost ≤$6.20/unit; delivery ≤3.5 days; zero disruption.","review_date":"2026-04-14","status":"succeeded","actual_outcome":"Shipping: $6.10/unit. Delivery: 3.1 days (40% improvement). Zero complaints. Annualized saving: $364K.","team":"Operations","owner":"Aiko Yamamoto","decided_at":"2026-01-14"},
    {"id":42,"title":"Migrate API services from EC2 to Kubernetes (EKS)","category":"operational","context":"6 fixed EC2 instances. Black Friday latency spiked to 4.2s. 45-minute deploys.","options_considered":[{"option":"Stay on EC2","pros":["familiar"],"cons":["doesn't solve spikes"]},{"option":"Migrate to EKS","pros":["autoscaling","8-min deploys","22% cost reduction"],"cons":["3-4 week effort"]},{"option":"AWS Lambda","pros":["infinite scale"],"cons":["cold starts","not for stateful services"]}],"data_consulted":["Black Friday postmortem","EC2 cost analysis ($18K/month)"],"decision_made":"Migrate all 6 services to EKS. Target March 15.","rationale":"Black Friday proved fixed instances can't handle traffic spikes.","expected_outcome":"API p99 ≤800ms at 3× traffic; deploy time ≤10 min; cost reduction ≥18%.","review_date":"2026-04-28","status":"succeeded","actual_outcome":"EKS operational March 14. p99 at 3×: 520ms. Deploy: 7 min. Cost: $13.8K/month (23% reduction).","team":"Engineering","owner":"Paulo Rivera","decided_at":"2026-01-28"},
    {"id":43,"title":"Migrate cloud infrastructure from GCP to AWS","category":"operational","context":"Team has stronger AWS expertise. AWS is $23K/month cheaper. CDN performance gap on media workload.","options_considered":[{"option":"Stay on GCP","pros":["no migration"],"cons":["$23K/month premium"]},{"option":"Full AWS migration","pros":["$276K/year saving","CDN improvement"],"cons":["3-month effort"]},{"option":"Hybrid","pros":["phased risk"],"cons":["hybrid costs more"]}],"data_consulted":["GCP vs AWS cost comparison","Engineering cloud certifications"],"decision_made":"Full GCP to AWS migration. 8-week plan. Target May 10.","rationale":"AWS is right long-term given team expertise and $276K saving.","expected_outcome":"AWS bill ≤$62K/month; CDN p95 improvement ≥20%; zero data loss.","review_date":"2026-05-10","status":"succeeded","actual_outcome":"Completed May 8. AWS bill: $59K. CDN improvement: 34%. Zero data loss. GCP terminated May 15.","team":"Engineering","owner":"Paulo Rivera","decided_at":"2026-02-10"},
    {"id":44,"title":"Replace legacy payment processor with Stripe","category":"operational","context":"Braintree has 3.2% failure rate (3× benchmark). International failures at 7.1%.","options_considered":[{"option":"Stay on Braintree","pros":["no switching cost"],"cons":["3.2% failure = $390K/year lost"]},{"option":"Switch to Stripe","pros":["smart retry","EU payment methods"],"cons":["4-week integration"]},{"option":"Stripe as secondary","pros":["lower risk"],"cons":["dual-processor complexity"]}],"data_consulted":["Payment failure rate analysis","Stripe ROI calculator"],"decision_made":"Replace Braintree with Stripe as sole processor.","rationale":"Payment failure is a direct revenue leak and churn trigger.","expected_outcome":"Failure rate ≤1.2%; international ≤2.0%; involuntary churn decrease ≥30%.","review_date":"2026-04-25","status":"succeeded","actual_outcome":"Failure: 1.1%. International: 1.8%. Involuntary churn -41%. Dunning recovered $28K in 30 days.","team":"Engineering","owner":"Paulo Rivera","decided_at":"2026-02-25"},
    {"id":45,"title":"Automate box curation with ML demand forecasting","category":"operational","context":"Manual curation: 40 person-hours/week. 12% repeat-product rate.","options_considered":[{"option":"Keep manual","pros":["human judgment"],"cons":["40 hrs/week","12% repeats"]},{"option":"ML-automated with human QA","pros":["scales","reduces repeats"],"cons":["4-week build"]},{"option":"Rule-based automation","pros":["faster build"],"cons":["can't handle personalization"]}],"data_consulted":["Category team time audit","Repeat-product rate analysis"],"decision_made":"Build ML-automated curation pipeline. Category team shifts to QA review.","rationale":"Addresses both the 12% repeat rate and 40 hr/week manual cost.","expected_outcome":"Curation time ≤8 hrs/week; repeat rate ≤3%; satisfaction ≥4.2/5.","review_date":"2026-06-04","status":"succeeded","actual_outcome":"Curation: 5 hrs/week (87.5% reduction). Repeat rate: 1.4%. Satisfaction: 4.4/5. 94% automation rate.","team":"Operations","owner":"Aiko Yamamoto","decided_at":"2026-03-04"},
    {"id":46,"title":"Pilot zero-waste biodegradable inner packaging","category":"operational","context":"Premium biodegradable alternatives quoted at 45% higher cost per unit.","options_considered":[{"option":"Keep current","pros":["lowest cost"],"cons":["contradicts sustainability brand"]},{"option":"Switch to Novamont biodegradable","pros":["full sustainability story"],"cons":["45% cost increase"]},{"option":"Partial: tissue only","pros":["lower cost"],"cons":["incomplete story"]}],"data_consulted":["Novamont product proposal","Inner packaging sustainability survey"],"decision_made":"Pilot Novamont materials for 30% of boxes in April.","rationale":"Pilot limits exposure while validating structural integrity.","expected_outcome":"Damage rate ≤2.5%; NPS ≥3 point lift; COGS ≤€0.15/box increase.","review_date":"2026-06-20","status":"reversed","actual_outcome":"Damage rate: 7.8% — 3.7× threshold. COGS: €0.41/box (vs €0.13 projected). NPS: flat. Reversed June 2.","team":"Operations","owner":"Aiko Yamamoto","decided_at":"2026-03-20"},
    {"id":47,"title":"Implement Snowflake as centralized data warehouse","category":"operational","context":"Data siloed across PostgreSQL, Sheets, Stripe, Shipbob. DS team bottlenecked.","options_considered":[{"option":"Continue ad-hoc pulls","pros":["no cost"],"cons":["6+ hrs/week wasted"]},{"option":"Snowflake + dbt","pros":["industry standard","Fivetran connectors"],"cons":["$2,800/month"]},{"option":"BigQuery","pros":["already have GCP"],"cons":["switching to AWS"]}],"data_consulted":["Data engineering time audit","Snowflake vs BigQuery evaluation"],"decision_made":"Implement Snowflake with Fivetran and dbt. 12 core dashboards.","rationale":"Right choice given AWS migration and Fivetran connector availability.","expected_outcome":"Cross-domain data within 24 hours; ad-hoc extraction ≤1 hr/week.","review_date":"2026-09-06","status":"active","actual_outcome":None,"team":"Engineering","owner":"Priya Menon","decided_at":"2026-04-14"},
    {"id":48,"title":"Implement Segment as Customer Data Platform","category":"operational","context":"Customer data fragmented across GA4, Mixpanel, Klaviyo, PostgreSQL.","options_considered":[{"option":"Keep fragmented tools","pros":["no cost"],"cons":["personalization impossible"]},{"option":"Segment as CDP","pros":["unified identity","real-time for ML"],"cons":["$3,200/month"]},{"option":"Build internal event bus","pros":["full control"],"cons":["12-week build"]}],"data_consulted":["Martech stack audit","Segment pricing","22% marketing over-spend estimate"],"decision_made":"Implement Segment. Connect website, apps, email, PostgreSQL.","rationale":"Identity fragmentation costs 22% marketing over-spend and blocks cross-channel personalization.","expected_outcome":"Identity match ≥90%; marketing deduplication ≥15%; ML events within 15 min.","review_date":"2026-09-06","status":"active","actual_outcome":None,"team":"Engineering","owner":"Aiko Yamamoto","decided_at":"2026-05-06"},
    {"id":49,"title":"Replace legacy ERP with NetSuite","category":"operational","context":"QuickBooks can't handle multi-currency, EU VAT, or intercompany transactions.","options_considered":[{"option":"Extend QuickBooks","pros":["low cost"],"cons":["limited multi-currency"]},{"option":"Migrate to NetSuite","pros":["full multi-currency","EU VAT built-in"],"cons":["$48K implementation"]},{"option":"Xero intermediate step","pros":["lower cost"],"cons":["another migration later"]}],"data_consulted":["QuickBooks limitations audit","NetSuite implementation proposal"],"decision_made":"Implement NetSuite via Deloitte partner. October 28 go-live.","rationale":"Can't operate on QuickBooks at this scale. Better to do it now than during fundraise.","expected_outcome":"Live by Oct 28; EU VAT automated; QuickBooks retired by Dec 31.","review_date":"2026-10-28","status":"active","actual_outcome":None,"team":"Finance","owner":"Nadia Osei","decided_at":"2026-05-28"},
    {"id":50,"title":"Implement real-time inventory tracking across all 3PL partners","category":"operational","context":"Inventory via daily CSV export. 24-hour lag causes 8% partial fulfillment rate.","options_considered":[{"option":"Continue daily CSV","pros":["no engineering"],"cons":["8% partial fulfillment"]},{"option":"Real-time webhooks from all 3PLs","pros":["intraday stockout detection"],"cons":["3 weeks per 3PL"]},{"option":"15% safety stock buffer","pros":["immediate"],"cons":["$28K/month excess inventory"]}],"data_consulted":["Partial fulfillment analysis (8.1%)","3PL API capability audit"],"decision_made":"Real-time webhooks for all 3 3PLs. Shipbob first, then Clipper, then Relais Colis.","rationale":"Real-time inventory is foundational for multi-3PL global operations.","expected_outcome":"Partial fulfillment ≤1.5%; stockout detection ≤15 minutes.","review_date":"2026-11-16","status":"active","actual_outcome":None,"team":"Operations","owner":"Aiko Yamamoto","decided_at":"2026-06-16"},
]

