    {"decision_id":1,"reviewer":"Nadia Osei","actual_outcome":"ARR lift $2.4M, churn 2.1%. Price-lock offer absorbed highest-risk cohort.","outcome_rating":5,"lessons_learned":"Give existing subscribers 60-day advance notice with a tangible retention offer.","reviewed_at":"2026-06-06"},
