    {"decision_id":25,"reviewer":"Paulo Rivera","actual_outcome":"API p95: 290ms. Payment uptime: 99.97%. OpenTelemetry + retry logic in 4 weeks.","outcome_rating":5,"lessons_learned":"Give infrastructure engineers outcome targets, not task lists.","reviewed_at":"2026-04-06"},
