    {"decision_id":34,"reviewer":"Marco Delgado","actual_outcome":"662 Canadian subscribers (+32%). CAC C$38. Margin 38%. Delivery 3.8-4.2 days.","outcome_rating":5,"lessons_learned":"Ohio-to-Toronto is effectively domestic. Template for English-speaking market entry.","reviewed_at":"2026-05-08"},
    {"decision_id":35,"reviewer":"Marco Delgado","actual_outcome":"142 subscribers (53% of target). Unit cost AUD$31 vs $18 model. Market exit.","outcome_rating":1,"lessons_learned":"Always get country-specific logistics quotes including customs inspection probability.","reviewed_at":"2026-05-24"},
