def get_decisions_df() -> pd.DataFrame:
    """Return all decisions as a DataFrame."""
    df = pd.DataFrame(DECISIONS)
    df["decided_at"] = pd.to_datetime(df["decided_at"])
    df["review_date"] = pd.to_datetime(df["review_date"])
    return df


def get_reviews_df() -> pd.DataFrame:
    """Return all reviews as a DataFrame."""
    df = pd.DataFrame(REVIEWS)
    df["reviewed_at"] = pd.to_datetime(df["reviewed_at"])
    return df


# ── Analytics (replicate SQL views in pandas) ────────────────────────────────

def compute_summary(df: pd.DataFrame) -> dict:
    """v_decision_summary — single-row executive summary."""
    today = pd.Timestamp.now()
    total = len(df)
    active = (df["status"] == "active").sum()
    succeeded = (df["status"] == "succeeded").sum()
    failed = (df["status"] == "failed").sum()
    reversed_ = (df["status"] == "reversed").sum()
    superseded = (df["status"] == "superseded").sum()
    overdue = ((df["review_date"] < today) & (df["status"] == "active")).sum()
    terminal = succeeded + failed + reversed_ + superseded
    accuracy = round(succeeded / terminal * 100, 1) if terminal > 0 else 0
    reversal = round(reversed_ / total * 100, 1) if total > 0 else 0
    return {
        "total_decisions": int(total),
        "active_decisions": int(active),
        "succeeded_decisions": int(succeeded),
        "failed_decisions": int(failed),
        "reversed_decisions": int(reversed_),
        "superseded_decisions": int(superseded),
        "overdue_decisions": int(overdue),
        "overall_accuracy_pct": accuracy,
        "overall_reversal_pct": reversal,
    }


def compute_accuracy(df: pd.DataFrame) -> pd.DataFrame:
    """v_decision_accuracy — success rate by category for terminal decisions."""
    terminal = df[df["status"].isin(["succeeded", "failed", "reversed", "superseded"])].copy()
    if terminal.empty:
        return pd.DataFrame()
    rows = []
    for cat, grp in terminal.groupby("category"):
        total = len(grp)
        s = (grp["status"] == "succeeded").sum()
        f = (grp["status"] == "failed").sum()
        r = (grp["status"] == "reversed").sum()
        sp = (grp["status"] == "superseded").sum()
        rate = round(s / total * 100, 1) if total > 0 else 0
        rows.append({"category": cat, "total_terminal": total, "succeeded": s,
                      "failed": f, "reversed": r, "superseded": sp,
                      "accuracy_rate_pct": rate})
    return pd.DataFrame(rows).sort_values("accuracy_rate_pct", ascending=False)


def compute_velocity(df: pd.DataFrame) -> pd.DataFrame:
    """v_decision_velocity — horizon and volume by category and month."""
    df2 = df.copy()
    df2["horizon_days"] = (df2["review_date"] - df2["decided_at"]).dt.days
    df2["month_bucket"] = df2["decided_at"].dt.to_period("M").dt.to_timestamp()
    today = pd.Timestamp.now()
    rows = []
    for (cat, mb), grp in df2.groupby(["category", "month_bucket"]):
        overdue = ((grp["review_date"] < today) & (grp["status"] == "active")).sum()
        rows.append({
            "category": cat, "month_bucket": mb,
            "total_decisions": len(grp),
            "avg_horizon_days": round(grp["horizon_days"].mean()),
            "min_horizon_days": int(grp["horizon_days"].min()),
            "max_horizon_days": int(grp["horizon_days"].max()),
            "overdue_count": int(overdue),
        })
    return pd.DataFrame(rows).sort_values(["category", "month_bucket"])


def compute_compliance(df: pd.DataFrame, reviews_df: pd.DataFrame) -> pd.DataFrame:
    """v_review_compliance — % of past-due decisions with at least one review."""
    today = pd.Timestamp.now()
    past_due = df[df["review_date"] < today].copy()
    if past_due.empty:
        return pd.DataFrame()
    reviewed_ids = set(reviews_df["decision_id"].unique())
    past_due["is_reviewed"] = past_due["id"].isin(reviewed_ids)
    rows = []
    for cat, grp in past_due.groupby("category"):
        total = len(grp)
        reviewed = grp["is_reviewed"].sum()
        rate = round(reviewed / total * 100, 1) if total > 0 else 0
        rows.append({"category": cat, "past_due_decisions": total,
                      "reviewed_count": int(reviewed), "compliance_rate_pct": rate})
    return pd.DataFrame(rows).sort_values("compliance_rate_pct", ascending=True)


def compute_reversal_rate(df: pd.DataFrame) -> pd.DataFrame:
    """v_reversal_rate — reversal and failure rates by category."""
    rows = []
    for cat, grp in df.groupby("category"):
        total = len(grp)
        rev = (grp["status"] == "reversed").sum()
        fail = (grp["status"] == "failed").sum()
        adverse = rev + fail
        rows.append({
            "category": cat, "total_decisions": total,
            "reversed_count": int(rev), "failed_count": int(fail),
            "adverse_count": int(adverse),
            "reversal_rate_pct": round(rev / total * 100, 1) if total > 0 else 0,
            "adverse_rate_pct": round(adverse / total * 100, 1) if total > 0 else 0,
        })
    return pd.DataFrame(rows).sort_values("adverse_rate_pct", ascending=False)
